			public static Binding TryMatch(GroupSpec g, global::System.Collections.Generic.List<Token> tokens, int argCount, out CmdException error)
			{
				error = null;
				var values = new global::System.Collections.Generic.List<string>[argCount];
				var specs = new ArgSpec[argCount];
				for (int k = 0; k < g.Positional.Length; ++k) specs[g.Positional[k].Id] = g.Positional[k];
				for (int k = 0; k < g.Named.Length; ++k) specs[g.Named[k].Id] = g.Named[k];
				string group = string.IsNullOrEmpty(g.Name) ? null : g.Name;
				int pos = 0;
				for (int i = 0; i < tokens.Count; ++i)
				{
					var t = tokens[i];
					if (t.Kind == TokenKind.Value)
					{
						if (t.Attached || pos >= g.Positional.Length)
						{
							error = new CmdException("Unexpected argument \"" + t.Raw + "\".", null, group);
							return null;
						}
						var sp = g.Positional[pos];
						if (values[sp.Id] == null) values[sp.Id] = new global::System.Collections.Generic.List<string>();
						values[sp.Id].Add(t.Text);
						if (sp.Kind != ArgKind.List) ++pos;
						continue;
					}
					var spec = g.Find(t);
					if (spec == null)
					{
						error = new CmdException("Unknown switch " + t.Raw + ".", t.Raw, group);
						return null;
					}
					bool hasNext = i + 1 < tokens.Count;
					bool nextAttached = hasNext && tokens[i + 1].Kind == TokenKind.Value && tokens[i + 1].Attached;
					switch (spec.Kind)
					{
						case ArgKind.Flag:
							if (values[spec.Id] != null)
							{
								error = new CmdException("Switch " + spec.Display + " was given more than once.", spec.Display, group);
								return null;
							}
							values[spec.Id] = new global::System.Collections.Generic.List<string>();
							if (nextAttached)
							{
								values[spec.Id].Add(tokens[i + 1].Text);
								++i;
							}
							else
							{
								values[spec.Id].Add("true");
							}
							break;
						case ArgKind.Scalar:
							if (t.BundledNotLast)
							{
								error = new CmdException("Switch " + t.Raw + " takes a value, so it can only be the last letter in a group like -abc.", spec.Display, group);
								return null;
							}
							if (values[spec.Id] != null)
							{
								error = new CmdException("Switch " + spec.Display + " was given more than once.", spec.Display, group);
								return null;
							}
							if (!hasNext || tokens[i + 1].Kind != TokenKind.Value)
							{
								error = new CmdException("Switch " + spec.Display + " needs a value.", spec.Display, group);
								return null;
							}
							values[spec.Id] = new global::System.Collections.Generic.List<string>(1) { tokens[i + 1].Text };
							++i;
							break;
						case ArgKind.List:
							if (t.BundledNotLast)
							{
								error = new CmdException("Switch " + t.Raw + " takes values, so it can only be the last letter in a group like -abc.", spec.Display, group);
								return null;
							}
							if (values[spec.Id] == null) values[spec.Id] = new global::System.Collections.Generic.List<string>();
							if (nextAttached)
							{
								values[spec.Id].Add(tokens[i + 1].Text);
								++i;
							}
							while (i + 1 < tokens.Count && tokens[i + 1].Kind == TokenKind.Value && !tokens[i + 1].Attached)
							{
								values[spec.Id].Add(tokens[i + 1].Text);
								++i;
							}
							break;
					}
				}
				for (int k = 0; k < g.Positional.Length; ++k)
				{
					var sp = g.Positional[k];
					if (sp.Required && (values[sp.Id] == null || values[sp.Id].Count == 0))
					{
						error = new CmdException("Missing required argument " + sp.Display + ".", sp.Display, group);
						return null;
					}
				}
				for (int k = 0; k < g.Named.Length; ++k)
				{
					var sp = g.Named[k];
					if (sp.Required && values[sp.Id] == null)
					{
						error = new CmdException("Missing required switch " + sp.Display + ".", sp.Display, group);
						return null;
					}
					if (sp.Required && sp.Kind == ArgKind.List && values[sp.Id].Count == 0)
					{
						error = new CmdException("Switch " + sp.Display + " needs at least one value.", sp.Display, group);
						return null;
					}
				}
				return new Binding { Group = g, Values = values, SpecsById = specs };
			}

			/// <summary>Wraps a conversion failure in a <see cref="CmdException"/> naming the argument.</summary>
			public static CmdException ConversionError(Binding binding, int id, string value, global::System.Exception inner)
			{
				var spec = binding.SpecsById[id];
				string display = spec != null ? spec.Display : null;
				string group = string.IsNullOrEmpty(binding.Group.Name) ? null : binding.Group.Name;
				return new CmdException("Invalid value \"" + value + "\" for " + display + ": " + inner.Message, display, group, inner);
			}
			#endregion

			#region Conversions
			public static bool ParseBool(string value)
			{
				switch ((value ?? "").Trim().ToLowerInvariant())
				{
					case "true": case "yes": case "on": case "1": return true;
					case "false": case "no": case "off": case "0": return false;
				}
				throw new global::System.FormatException("Expected true or false.");
			}

			/// <summary>Opens a file for reading, or returns standard input for "-".</summary>
			public static global::System.IO.TextReader OpenReader(string path)
			{
				if (path == "-") return global::System.Console.In;
				return new global::System.IO.StreamReader(path);
			}

			/// <summary>Returns a writer for a file that is created on first write, or standard output for "-".</summary>
			public static global::System.IO.TextWriter OpenWriter(string path)
			{
				if (path == "-") return global::System.Console.Out;
				if (string.IsNullOrEmpty(path)) throw new global::System.ArgumentException("The path is empty.");
				return new DeferredTextWriter(path);
			}
			#endregion

			#region Disposal
			static bool IsConsoleStream(object value)
			{
				return ReferenceEquals(value, global::System.Console.In) || ReferenceEquals(value, global::System.Console.Out)
					|| ReferenceEquals(value, global::System.Console.Error);
			}

			/// <summary>
			/// Disposes an argument value: the value itself if it is disposable, otherwise each disposable item when it is a
			/// collection. The console's standard streams are never disposed. Returns true if anything was disposed.
			/// </summary>
			public static bool DisposeArgument(object value)
			{
				if (value == null || value is string || IsConsoleStream(value)) return false;
				var disposable = value as global::System.IDisposable;
				if (disposable != null)
				{
					disposable.Dispose();
					return true;
				}
				var items = value as global::System.Collections.IEnumerable;
				if (items == null) return false;
				bool any = false;
				foreach (var item in items)
				{
					var d = item as global::System.IDisposable;
					if (d != null && !IsConsoleStream(item))
					{
						d.Dispose();
						any = true;
					}
				}
				return any;
			}
			#endregion

			#region Usage
			/// <summary>Appends ". Defaults to X." to a description when the default is worth showing.</summary>
			public static string WithDefault(string description, object value)
			{
				string text = FormatDefault(value);
				if (string.IsNullOrEmpty(text)) return description;
				if (!string.IsNullOrEmpty(description) && description.IndexOf("default", global::System.StringComparison.OrdinalIgnoreCase) >= 0) return description;
				if (string.IsNullOrEmpty(description)) return "Defaults to " + text + ".";
				string d = description.TrimEnd();
				if (!d.EndsWith(".")) d += ".";
				return d + " Defaults to " + text + ".";
			}

			public static string FormatDefault(object value)
			{
				if (value == null) return null;
				if (ReferenceEquals(value, global::System.Console.In)) return "<stdin>";
				if (ReferenceEquals(value, global::System.Console.Out)) return "<stdout>";
				if (ReferenceEquals(value, global::System.Console.Error)) return "<stderr>";
				var deferred = value as DeferredTextWriter;
				if (deferred != null) return Quote(deferred.Name);
				var reader = value as global::System.IO.TextReader;
				if (reader != null) return Quote(GetFilename(reader));
				var writer = value as global::System.IO.TextWriter;
				if (writer != null) return Quote(GetFilename(writer));
				var s = value as string;
				if (s != null) return s.Length == 0 ? null : Quote(s);
				if (value is bool) return (bool)value ? "true" : "false";
				if (value is global::System.Collections.IEnumerable)
				{
					var parts = new global::System.Collections.Generic.List<string>();
					foreach (var item in (global::System.Collections.IEnumerable)value)
					{
						var p = FormatDefault(item);
						if (p != null) parts.Add(p);
					}
					return parts.Count == 0 ? null : string.Join(" ", parts.ToArray());
				}
				var f = value as global::System.IFormattable;
				if (f != null) return Quote(f.ToString(null, global::System.Globalization.CultureInfo.InvariantCulture));
				return Quote(value.ToString());
			}

			static string Quote(string s)
			{
				if (s == null) return null;
				for (int i = 0; i < s.Length; ++i)
				{
					if (char.IsWhiteSpace(s[i])) return "\"" + s + "\"";
				}
				return s;
			}

			const int Indent = 4;

			/// <summary>Finds a usage group by name; null means the first group.</summary>
			public static UsageGroup FindGroup(UsageGroup[] groups, string name)
			{
				if (name == null) return groups[0];
				for (int i = 0; i < groups.Length; ++i)
				{
					if (groups[i].Name == name) return groups[i];
				}
				throw new global::System.ArgumentException("There is no argument group named \"" + name + "\".", "group");
			}

			/// <summary>The synopsis line, e.g. "&lt;input&gt; [--verbose]", wrapped to the width.</summary>
			public static string Synopsis(UsageGroup group, int width, int startOffset)
			{
				return WordWrap(group.Synopsis, width == 0 ? ConsoleWidth : width, Indent * 2, startOffset);
			}

			/// <summary>The table of arguments and their descriptions for one group.</summary>
			public static string Descriptions(UsageGroup group, int width)
			{
				if (width == 0) width = ConsoleWidth;
				const int maxLeft = 28;
				int left = 0;
				for (int i = 0; i < group.Lefts.Length; ++i)
				{
					int len = group.Lefts[i].Length;
					if (len <= maxLeft && len > left) left = len;
				}
				int column = Indent + left + 2;
				if (column > width / 2) column = Indent + 2;
				var sb = new global::System.Text.StringBuilder();
				for (int i = 0; i < group.Lefts.Length; ++i)
				{
					string l = new string(' ', Indent) + group.Lefts[i];
					string desc = group.Descriptions[i] ?? "";
					if (desc.Length == 0)
					{
						sb.AppendLine(l);
						continue;
					}
					if (l.Length + 2 > column)
					{
						sb.AppendLine(l);
						l = "";
					}
					sb.Append(l);
					sb.Append(' ', column - l.Length);
					sb.AppendLine(WordWrap(desc, width, column, column));
				}
				return sb.ToString();
			}

			/// <summary>The whole usage screen: title, description, then each group's synopsis and argument table.</summary>
			public static string BuildUsage(global::System.Reflection.Assembly assembly, string exeName, string description, UsageGroup[] groups, int width)
			{
				if (width == 0) width = ConsoleWidth;
				var sb = new global::System.Text.StringBuilder();
				string title = null;
				string version = null;
				if (assembly != null)
				{
					var name = assembly.GetName();
					title = name.Name;
					if (name.Version != null) version = name.Version.ToString();
					var t = (global::System.Reflection.AssemblyTitleAttribute)global::System.Attribute.GetCustomAttribute(assembly, typeof(global::System.Reflection.AssemblyTitleAttribute));
					if (t != null && !string.IsNullOrEmpty(t.Title)) title = t.Title;
					if (string.IsNullOrEmpty(description))
					{
						var d = (global::System.Reflection.AssemblyDescriptionAttribute)global::System.Attribute.GetCustomAttribute(assembly, typeof(global::System.Reflection.AssemblyDescriptionAttribute));
						if (d != null) description = d.Description;
					}
				}
				if (!string.IsNullOrEmpty(title))
				{
					sb.AppendLine(WordWrap(version != null ? title + " v" + version : title, width, Indent));
					sb.AppendLine();
				}
				if (!string.IsNullOrEmpty(description))
				{
					sb.AppendLine(WordWrap(description, width, 0));
					sb.AppendLine();
				}
				string exe = string.IsNullOrEmpty(exeName) ? ExeName : exeName;
				if (groups.Length == 1)
				{
					string prefix = "Usage: " + exe + " ";
					sb.Append(prefix);
					sb.AppendLine(Synopsis(groups[0], width, prefix.Length));
					sb.AppendLine();
					sb.Append(Descriptions(groups[0], width));
				}
				else
				{
					sb.AppendLine("Usage:");
					for (int g = 0; g < groups.Length; ++g)
					{
						sb.AppendLine();
						string prefix = new string(' ', Indent) + exe + " ";
						sb.Append(prefix);
						sb.AppendLine(Synopsis(groups[g], width, prefix.Length));
						sb.AppendLine();
						sb.Append(Descriptions(groups[g], width));
					}
				}
				return sb.ToString();
			}
			#endregion
		}
	}
